<template><div class="page"><div class="page-head"><div><span>MODEL GOVERNANCE</span><h2>预测与诊断模型管理</h2><p>按项目技术路线登记模型、工程状态、证据来源与可部署性。</p></div><el-button @click="load" :loading="loading">刷新目录</el-button></div><el-alert title="模型名称登记不等于完成训练。没有权重、归一化参数或验证报告的模型会明确标为待集成。" type="warning" :closable="false"/><el-card shadow="never"><el-table :data="models"><el-table-column prop="name" label="模型" min-width="210"/><el-table-column prop="domain" label="业务方向"/><el-table-column prop="version" label="版本"/><el-table-column label="工程状态"><template #default="s"><el-tag :type="tagType(s.row.status)">{{statusText(s.row.status)}}</el-tag></template></el-table-column><el-table-column label="可调用"><template #default="s"><el-tag :type="s.row.deployable?'success':'info'">{{s.row.deployable?'是':'否'}}</el-tag></template></el-table-column><el-table-column prop="evidence" label="证据/限制" min-width="300"/></el-table></el-card></div></template>
<script setup>import{ref,onMounted}from'vue';const models=ref([]),loading=ref(false),statusText=s=>({trained:'已训练接入',development:'开发验证',adapter:'资产适配',pending_weights:'待权重与验证',missing_assets:'资产缺失'}[s]||s),tagType=s=>s==='trained'?'success':s==='development'?'success':s==='adapter'?'warning':'info';async function load(){loading.value=true;try{models.value=(await(await fetch('/api/v1/phm/model-catalog/')).json()).models||[]}finally{loading.value=false}}onMounted(load)</script>
<style scoped>.page{max-width:1250px}.page-head{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:18px}.page-head span{font-size:12px;color:#1677ff;letter-spacing:1px}.page-head h2{margin:8px 0}.page-head p{margin:0;color:#718198}.overview{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-bottom:16px}.overview strong{display:block;font-size:28px;margin:5px 0}.overview small,.overview span{color:#718198;font-size:13px}.success{color:#19a974}.layout{display:grid;grid-template-columns:420px 1fr;gap:16px}.card-title,.detail-head{display:flex;justify-content:space-between;align-items:center}.model-row{display:flex;align-items:center;gap:12px;padding:14px 10px;border:1px solid transparent;border-bottom-color:#edf1f5;cursor:pointer}.model-row.selected{background:#eef6ff;border-color:#9bc7f5}.model-icon{display:grid;place-items:center;width:40px;height:40px;border-radius:8px;background:#e8f2ff;color:#1677ff;font-weight:700;font-size:12px}.model-main{display:flex;flex:1;flex-direction:column;gap:3px}.model-main span,.model-main small,.detail-head p{color:#718198;font-size:12px}.detail-head h3{margin:0 0 6px}.metric-title{font-weight:600;margin:22px 0 12px}.metrics{display:grid;grid-template-columns:1fr 1fr;gap:22px}.metrics span{display:block;color:#718198;font-size:13px}.metrics b{display:block;margin:5px 0}.run-result{margin-top:16px}.el-alert{margin-bottom:16px}@media(max-width:800px){.page-head{display:block}.page-head .el-button{margin-top:14px}.overview,.layout{grid-template-columns:1fr}.metrics{grid-template-columns:1fr}}</style>
